"""Robot behaviour for Patio Scout."""

from config import LOOP_HZ, SERIAL_BAUD, PINS
import time


class Robot:
    """Starter control loop generated from the Albayraq pin map."""

    def __init__(self) -> None:
        self.running = False

    def setup(self) -> None:
        print("Booting Patio Scout")
        # TODO: initialise motors, sensors, and safe output states for your board.
        self.running = True

    def step(self) -> None:
        """Run one control iteration."""
        # TODO: read sensors, compute an error, and command the motors.
        # Pin names are available through ``PINS`` in config.py.
        time.sleep(1 / LOOP_HZ)

    def stop(self) -> None:
        self.running = False
        # TODO: drive every motor output to a safe low state.
        print("Stopped")


def make_robot() -> Robot:
    return Robot()

"""Entry point. Copy this project to the board, then run main.py."""

from robot import make_robot


def main() -> None:
    robot = make_robot()
    robot.setup()
    try:
        while robot.running:
            robot.step()
    except KeyboardInterrupt:
        pass
    finally:
        robot.stop()


if __name__ == "__main__":
    main()

